import {metrics,actors,actorDistance,shutterText,distanceText} from './physics.mjs';
export function stateRows(state){const m=metrics(state),s=m.s;return [
 ['Format',m.sensor.name],['Bauart',s.body==='dslr'?'DSLR':'Spiegellos'],['Modus',s.mode],['Brennweite',`${s.focal.toFixed(1)} mm`],['Blende',`ƒ/${Number(s.aperture.toFixed(1))}`],['Zeit',shutterText(s.time)],['ISO',`${Math.round(s.iso)}`],['Fokus',distanceText(s.focus)],['Autofokus',s.autoFocus?actors[s.afTarget].name:'aus'],['Szenenhelligkeit',`${s.ev.toFixed(1)} EV₁₀₀`],['Lichtfarbe',`${s.temperature} K`],['Weißabgleich',`${Math.round(s.wb)} K`],['ND',`${s.nd} EV`],['Korrektur',`${s.comp.toFixed(1)} EV`],['Sensorauflösung',`${s.mp} MP`],['Gehen',`${s.speed.toFixed(1)} m/s`],['Winken',`${s.waveSpeed.toFixed(1)} m/s`],['Balltempo',`${s.ballSpeed.toFixed(1)} m/s`],['Flugtempo',`${s.birdSpeed.toFixed(1)} m/s`],['Kamera zurück',`${s.cameraBack.toFixed(1)} m`],...Object.entries(actors).filter(([id])=>id!=='camera').flatMap(([id,a])=>[[`Abstand ${a.name}`,distanceText(actorDistance(s,id))],...(a.x?[[`${a.name} seitlich`,`${s[a.x].toFixed(1)} m`]]:[])]),['Kamera seitlich',`${s.cameraX.toFixed(1)} m`],['Stativ',s.tripod?'an':'aus'],['Stabilisierung',s.stabilization?'an':'aus'],['Porträteffekt',s.portrait?'an':'aus'],['Schärfemaßstab',s.cocMode==='pixel'?'2 Pixel':'Diagonale / 1500'],['Belichtungsabweichung',`${m.offset.toFixed(2)} EV`],['Licht pro Fläche',`${m.physical.toFixed(3)}×`],['Schärfebereich',`${distanceText(m.near)} – ${distanceText(m.far)}`]
 ];}
export function comparisonRows(a,b){const first=new Map(stateRows(a));return stateRows(b).filter(([key,value])=>first.get(key)!==value).map(([key,value])=>({key,a:first.get(key),b:value}));}
